<template><ul class="qnav-tree"><li v-for="row in rows" :key="row.id" :data-menu="row.id"><template v-if="row.kind==='group'"><button type="button" class="qnav-group" :aria-expanded="!folded.has(row.id)" @click="toggle(row.id)"><MenuIcon :row="row"/><b>{{menuLabel(row,currentLang)}}</b><ClientIcon :name="folded.has(row.id)?'chevronRight':'chevronDown'"/></button><template v-if="!folded.has(row.id)"><NavigationTree v-if="row.children?.length" :rows="row.children" :interactive="interactive" @navigate="$emit('navigate')"/><p v-else class="qnav-empty-group">{{nt('这个分组暂未添加入口')}}</p></template></template><MenuLink v-else :row="row" :interactive="interactive" :active="active(row)" @navigate="$emit('navigate')"/></li></ul></template>
<script setup>
import{ref}from'vue';import{useRoute}from'vue-router';import{currentLang}from'../../i18n/index.js';import{menuLabel}from'../../lib/navigation.js';import{navigationText}from'../../i18n/navigation-messages.js';import MenuLink from'./MenuLink.vue';import MenuIcon from'./MenuIcon.vue';import ClientIcon from'../reference/ClientIcon.vue';
defineProps({rows:{type:Array,default:()=>[]},interactive:{type:Boolean,default:true}});defineEmits(['navigate']);const route=useRoute(),folded=ref(new Set()),nt=value=>navigationText(currentLang.value,value),active=row=>row.path===route.fullPath||row.path===route.path||row.kind==='embed'&&route.params.id===row.id;
function toggle(id){const next=new Set(folded.value);next.has(id)?next.delete(id):next.add(id);folded.value=next;}
</script>
